-- Opening stock (DEMO). Written to the ledger so inventory always equals the sum of movements.
-- Only applied to variants that have no stock history yet, so re-running the seed is safe.
with opening (variant_id, qty, threshold) as (
  values
    (md5('ust-demo:variant:p-mf385-clutch-plate')::uuid, 14, 5),
    (md5('ust-demo:variant:p-fiat480-clutch-plate')::uuid, 22, 5),
    (md5('ust-demo:variant:p-mf240-pressure-plate')::uuid, 3, 5),
    (md5('ust-demo:variant:p-release-bearing')::uuid, 40, 5),
    (md5('ust-demo:variant:p-nh7056-friction-disc')::uuid, 9, 5),
    (md5('ust-demo:variant:p-clutch-finger-kit')::uuid, 0, 5),
    (md5('ust-demo:variant:p-belarus-clutch-plate')::uuid, 6, 5),
    (md5('ust-demo:variant:p-pilot-bush')::uuid, 30, 5),
    (md5('ust-demo:variant:p-starter-ring-gear')::uuid, 11, 5),
    (md5('ust-demo:variant:p-piston-liner-set')::uuid, 8, 5),
    (md5('ust-demo:variant:p-hydraulic-pump')::uuid, 4, 5),
    (md5('ust-demo:variant:p-engine-oil-20w50')::uuid, 60, 5),
    (md5('ust-demo:variant:p-gear-oil-90')::uuid, 12, 5),
    (md5('ust-demo:variant:p-hydraulic-oil')::uuid, 2, 5),
    (md5('ust-demo:variant:p-oil-filter')::uuid, 80, 5),
    (md5('ust-demo:variant:p-fuel-filter')::uuid, 35, 5),
    (md5('ust-demo:variant:p-grease-mp3')::uuid, 25, 5),
    (md5('ust-demo:variant:p-air-filter')::uuid, 18, 5),
    (md5('ust-demo:variant:p-rear-tyre')::uuid, 4, 5),
    (md5('ust-demo:variant:p-radiator')::uuid, 3, 5),
    (md5('ust-demo:variant:p-battery-cable')::uuid, 20, 5),
    (md5('ust-demo:variant:p-spanner-set')::uuid, 10, 5),
    (md5('ust-demo:variant:p-work-light')::uuid, 15, 5)
), fresh as (
  select o.* from opening o
   where o.qty > 0
     and not exists (select 1 from public.stock_movements m where m.variant_id = o.variant_id)
), updated as (
  update public.inventory i
     set on_hand = i.on_hand + f.qty, low_stock_threshold = f.threshold
    from fresh f
   where i.variant_id = f.variant_id
  returning i.variant_id, f.qty, i.on_hand, i.reserved
)
insert into public.stock_movements (variant_id, movement_type, on_hand_delta, on_hand_after, reserved_after, reason)
select variant_id, 'receive', qty, on_hand, reserved, 'DEMO opening stock' from updated;

